def choose_move(observation):
    w = observation.get("grid_width", 0)
    h = observation.get("grid_height", 0)
    me = observation.get("self_position") or [0, 0]
    opp = observation.get("opponent_position") or [0, 0]
    res = observation.get("resources") or []
    obs = observation.get("obstacles") or []
    sx, sy = int(me[0]), int(me[1])
    ox, oy = int(opp[0]), int(opp[1])

    def pos(v):
        if isinstance(v, dict):
            for k in ("position", "pos", "loc", "location", "xy"):
                p = v.get(k)
                if isinstance(p, (list, tuple)) and len(p) >= 2:
                    return int(p[0]), int(p[1])
        elif isinstance(v, (list, tuple)) and len(v) >= 2 and isinstance(v[0], (int, float)):
            return int(v[0]), int(v[1])
        return None

    blocks = set()
    for v in obs:
        p = pos(v)
        if p is not None:
            blocks.add(p)

    def free(x, y):
        return 0 <= x < w and 0 <= y < h and (x, y) not in blocks

    best = None
    bd = 10**9
    for v in res:
        p = pos(v)
        if p is None:
            continue
        d = abs(sx - p[0]) + abs(sy - p[1])
        if d < bd or (d == bd and p < best):
            best, bd = p, d

    moves = [(0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)]
    if best is None:
        moves.sort(key=lambda m: (abs((sx + m[0]) - ox) + abs((sy + m[1]) - oy), m[1], m[0]), reverse=True)
        for dx, dy in moves:
            if free(sx + dx, sy + dy):
                return [dx, dy]
        return [0, 0]

    bx, by = best
    opts = []
    for dx, dy in moves:
        nx, ny = sx + dx, sy + dy
        if not free(nx, ny):
            continue
        sd = abs(nx - bx) + abs(ny - by)
        od = abs(nx - ox) + abs(ny - oy)
        edge = min(nx, ny, w - 1 - nx, h - 1 - ny)
        score = (-sd, od, edge, -abs(dx) - abs(dy), dy, dx)
        opts.append((score, dx, dy))
    if not opts:
        return [0, 0]
    opts.sort(reverse=True)
    return [opts[0][1], opts[0][2]]

